      "cameraAngle": "角度枚举",
      "lens": "焦段枚举",
      "depthOfField": "景深枚举",
      "lighting": "光效枚举",
      "mood": "氛围枚举",
      "composition": "centered|rule_of_thirds|symmetrical",
      "actionChain": "动作A → 动作B → 动作C",
      "promptEn": "≥120词英文视频提示词（9:16 竖屏，六步公式 + 写实指令 + 眼神/对话）。角色外貌每镜重复完整描述(含显式性别+年龄)。",
      "negativePrompt": "负面屏蔽词（与 promptEn 分开，不混进 promptEn）：no creepy smile, no plastic skin, no uncanny valley, no distorted face, no deformed hands, no extra fingers, no jitter, no flicker, no watermark, no text overlay。",
      "promptZh": "中文描述",
